// Usage counters for installed skills/commands/agents, independent of
// whether they were generated by this plugin's own evolve lifecycle
// (lib/candidates.js) or hand-written: <project data dir>/usage.json,
// `{ skills: { id: {count, last} }, commands: { name: {...} }, agents:
// { name: {...} } }`. lib/observe.js bumps these as tool calls and
// prompts are observed; lib/board.js and lib/commands.js's /evolve-list
// read them back to judge whether an installed candidate is still used,
// and lib/maintain.js's pruneCandidatesStep reads them to decide what to
// flag or (opt-in) auto-archive.
import fs from "node:fs/promises";
import path from "node:path";
import { uniqueSuffix } from "./store.js";

const FILE_NAME = "usage.json";
export const USAGE_BUCKETS = ["skills", "commands", "agents"];

async function readUsageFile(projectDir) {
  try {
    const parsed = JSON.parse(await fs.readFile(path.join(projectDir, FILE_NAME), "utf8"));
    return typeof parsed === "object" && parsed !== null ? parsed : {};
  } catch {
    return {};
  }
}

async function writeUsageFile(projectDir, data) {
  await fs.mkdir(projectDir, { recursive: true });
  const file = path.join(projectDir, FILE_NAME);
  const tmp = path.join(projectDir, `.${FILE_NAME}.tmp-${uniqueSuffix()}`);
  await fs.writeFile(tmp, JSON.stringify(data, null, 2), "utf8");
  await fs.rename(tmp, file);
}

// Serialized per project directory: two tool calls observed in the same
// tick must never race a read-modify-write against the same usage.json
// (the same hazard lib/inject.js's fired-miss log already solves for a
// different shared file, with the same fix).
const queues = new Map();

function enqueue(projectDir, task) {
  const previous = queues.get(projectDir) ?? Promise.resolve();
  const next = previous.then(task, task);
  queues.set(projectDir, next.catch(() => {}));
  return next;
}

// Increments (or starts at 1) `usage[bucket][key].count` and stamps
// `.last` to now. Returns the updated `{count, last}` entry so a caller
// that wants to react to "this was just used" (lib/observe.js's
// installed-candidate fired-bump feedback) never needs a second read.
export async function bumpUsage(projectDir, bucket, key) {
  if (!USAGE_BUCKETS.includes(bucket) || typeof key !== "string" || key.length === 0) return null;
  return enqueue(projectDir, async () => {
    const data = await readUsageFile(projectDir);
    const section = typeof data[bucket] === "object" && data[bucket] !== null ? data[bucket] : {};
    const previous = typeof section[key] === "object" && section[key] !== null ? section[key] : { count: 0, last: null };
    const entry = { count: (Number(previous.count) || 0) + 1, last: new Date().toISOString() };
    section[key] = entry;
    data[bucket] = section;
    await writeUsageFile(projectDir, data);
    return entry;
  });
}

export async function readUsage(projectDir) {
  const data = await readUsageFile(projectDir);
  const result = {};
  for (const bucket of USAGE_BUCKETS) {
    result[bucket] = typeof data[bucket] === "object" && data[bucket] !== null ? data[bucket] : {};
  }
  return result;
}

export async function usageEntryFor(projectDir, bucket, key) {
  const usage = await readUsage(projectDir);
  const entry = usage[bucket]?.[key];
  return { count: Number(entry?.count) || 0, last: entry?.last ?? null };
}

// True when `usage[bucket]` has never recorded a single key: the whole
// signal for that kind looks dead (e.g. a host naming its skill tool, or
// its input field, differently than this plugin expects, see
// lib/observe.js's trackToolUsage), not merely "nothing happens to be
// unused right now". lib/maintain.js's pruneCandidatesStep's auto mode
// uses this to refuse to delete anything of a kind whose usage bucket is
// entirely empty, rather than treating a broken signal as proof every
// installed candidate of that kind is unused.
export function isUsageBucketEmpty(usage, bucket) {
  const section = usage?.[bucket];
  return !section || Object.keys(section).length === 0;
}

// A slash command's name, parsed from raw prompt text ("/evolve-install
// abc" -> "evolve-install"), or null when the text is not a slash
// command at all. Only the leading token matters: anything typed after
// the command name (arguments) is not part of its identity for counting
// purposes.
export function commandNameFromPromptText(text) {
  if (typeof text !== "string") return null;
  const match = /^\s*\/([a-zA-Z0-9][a-zA-Z0-9_-]*)/.exec(text);
  return match ? match[1] : null;
}
